from pathlib import Path
from html import escape as e
import json,re
R=Path(__file__).parent;root=R.parent
data=json.load(open(root/'grammar-data.json'));catalog=json.load(open(R/'verified-catalog.json'));byid={v['id']:v for v in catalog};stages=data['stages']
count=sum(bool(l['video_ids']) for s in stages for l in s['lessons']);gaps=sum(not l['video_ids'] for s in stages for l in s['lessons']);ids={id for s in stages for l in s['lessons'] for id in l['video_ids']}
def video(id):
 v=byid[id];return f'<a class="video-link" href="{e(v["url"])}" target="_blank" rel="noopener noreferrer">{e(v["verified_title"])} ↗</a><span class="duration">{e(v.get("duration", "Short practice video"))}</span>'
nav=''.join(f'<a href="#{s["id"]}">{e(s["title"])}</a>' for s in stages)
sections='';n=0
for s in stages:
 rows=''
 for l in s['lessons']:
  n+=1;vids=l['video_ids'];topic=l['topic'];desc=l['description']
  search=(topic+' '+desc+' '+' '.join(byid[id]['verified_title'] for id in vids)).lower()
  control=f'<label class="done-label"><input type="checkbox" data-lesson="{e(l["id"])}" aria-label="Complete: {e(topic)}"></label>' if vids else '<span class="gap-explainer" aria-label="No verified lesson">—</span>'
  links=video(vids[0]) if vids else '<span class="gap-badge">No matching public video found</span><p class="gap-explainer">Not proof of absence. See coverage notes below.</p>'
  if len(vids)>1:links+='<details class="alternatives"><summary>Optional older lessons / extra practice</summary>'+''.join(video(id) for id in vids[1:])+'</details>'
  if 'Go to do:' in topic:
   links='<span class="gap-badge">Older public link unverified</span><p class="gap-explainer">Misa’s <a href="https://www.japaneseammo.com/34-go-to-do-purpose-in-order-to-%E2%94%83japanese-grammar-lesson/" target="_blank" rel="noopener">official text lesson</a> remains discoverable. Video metadata returned 403.</p>'
  if 'Embedded questions:' in topic:links+='<p class="gap-explainer"><a href="https://www.japaneseammo.com/all-about-%E3%81%8B-its-not-only-a-question-marker/" target="_blank" rel="noopener">Misa’s related text article ↗</a></p>'
  if 'こと vs の:' in topic:links+='<p class="gap-explainer"><a href="https://www.japaneseammo.com/talking-about-hobbies-completely-in-japanese-with-english-subs/" target="_blank" rel="noopener">Misa’s related text article ↗</a></p>'
  rows+=f'<tr id="{l["id"]}" data-topic="{e(search)}"><td><span class="lesson-number">{n:03}</span>{control}</td><td><span class="topic">{e(topic)}</span></td><td class="desc">{e(desc)}</td><td>{links}</td></tr>'
 sections+=f'<section id="{s["id"]}" class="stage" aria-labelledby="{s["id"]}-heading"><header class="stage-header"><h2 id="{s["id"]}-heading">{e(s["title"])}<span class="stage-count"></span></h2><p>{e(s["note"])}</p></header><div class="table-wrap"><table><caption class="sr-only">{e(s["title"])} lessons in learning order</caption><thead><tr><th scope="col">Done</th><th scope="col">Grammar point</th><th scope="col">What you’ll learn</th><th scope="col">Misa’s video</th></tr></thead><tbody>{rows}</tbody></table></div></section>'
playlists=json.load(open(R/'playlists.json'))
source_links=''.join(f'<li><a href="{e(p["url"])}" target="_blank" rel="noopener">{e(p["name"])}</a> — {len(p["videos"])} entries inspected.</li>' for p in playlists)
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A personal Japanese grammar course using Japanese Ammo with Misa videos, organized in learning order with saved progress."><title>Japanese grammar course · Japanese learner</title><link rel="stylesheet" href="grammar.css"><script src="grammar.js" defer></script></head><body><a class="skip" href="#course">Skip to course</a><header class="topbar"><span class="brand" lang="en">Japanese learner</span><nav class="site-nav" aria-label="Study pages"><a href="index.html">Reading articles</a><a href="grammar.html" aria-current="page">Grammar course</a></nav></header><div class="layout"><aside class="sidebar"><h2>Learning order</h2><nav class="stages" aria-label="Course stages">{nav}</nav><a class="scope-link" href="#coverage">Sources & coverage notes ↓</a></aside><main id="course"><p class="eyebrow">Japanese Ammo with Misa · Personal course</p><h1>Pick up where you left off.</h1><p class="intro">Tick the basics you already know, then take one lesson at a time. {count} lesson entries · {len(ids)} linked videos · {gaps} coverage gaps. The order is curated for learning, not upload date.</p><div class="progress-panel"><div class="progress-copy"><strong id="progress-label" aria-live="polite">0 of {count} lessons complete</strong><progress id="progress" max="{count}" value="0" aria-label="Course completion"></progress><small>Saved in this browser on this address. Gaps and optional extra videos are not counted.</small></div><button class="continue" id="continue" type="button">Continue learning →</button></div><p id="storage-warning" class="storage-warning" role="status" hidden>Progress could not be loaded or saved. Your checkmarks work for this visit, but may not survive a reload.</p><noscript><p>Enable JavaScript for saved checkmarks, filtering, and the Continue button. All lessons and links are available below.</p></noscript><div class="controls"><label for="search">Find a grammar point<input id="search" type="search" placeholder="e.g. ている, passive, conditionals" autocomplete="off"></label><label for="status">Show<select id="status"><option value="all">All entries</option><option value="todo">Unfinished lessons</option><option value="done">Completed lessons</option><option value="gaps">Coverage gaps</option></select></label></div><p id="results" class="results" role="status">{n} entries in learning order</p><p id="empty" class="empty" hidden>No entries match. Try another word or choose “All entries”.</p>{sections}<details id="coverage" class="scope"><summary>Sources, verification & coverage · checked 13 September 2026</summary><p>This is an independent course built around Misa’s public material. Stage order and short learning goals are editorial; they are not Misa’s official course order or a complete JLPT syllabus.</p><ul><li>Inspected <a href="https://www.youtube.com/@JapaneseAmmowithMisa/videos" target="_blank" rel="noopener">the channel’s Videos tab</a> through all 10 returned pages (299 uploads), its <a href="https://www.youtube.com/@JapaneseAmmowithMisa/shorts" target="_blank" rel="noopener">Shorts tab</a> (7 shorts), and nine relevant channel-owned playlists. Also checked the official grammar archive and targeted searches for gaps. The <a href="https://bunpro.jp/grammar_points" target="_blank" rel="noopener">Bunpro grammar library</a> was used to cross-check prerequisite coverage, especially beginner and intermediate foundations. This is not a point-for-point mapping of the full Bunpro library; descriptions are original.</li><li>All {len(ids)} distinct video links in this course returned YouTube oEmbed metadata identifying “Japanese Ammo with Misa” as the author. Titles were checked against that metadata. This verifies identity and metadata availability, not successful playback in every region. Videos were not watched end to end.</li><li>306 public video IDs were verified in the research inventory. Grammar-focused material is organized here, including older versions and selected review/application lessons. Pure vocabulary, kanji, pronunciation, vlogs, and cultural videos are generally outside this course.</li><li>“No matching public video found” means no dedicated match was found in the inspected catalog, playlists, official archive, or targeted discovery. Some points may occur inside broader lessons. It does not establish that Misa has never covered them.</li><li>Two historical links from the official website (#33 and #34) returned 403 from YouTube oEmbed. They are not counted as verified videos. A newer obligation lesson covers #33’s main topic; #34 remains an explicit gap. The cause of the 403 response was not established.</li><li>The available public index cannot guarantee discovery of deleted, private, unlisted, members-only, or all material embedded in livestreams. The official archive’s fourth page could not be retrieved. No other channels have been substituted.</li><li>Saved progress is local to this browser and address. Use <strong>http://127.0.0.1:8765/grammar.html</strong> consistently; a different browser, port, hostname, or file URL has separate storage.</li></ul><h3>Channel playlists inspected</h3><ul>{source_links}</ul><p><a href="https://www.japaneseammo.com/category/grammar/" target="_blank" rel="noopener">Official grammar archive</a> · <a href="https://www.japaneseammo.com/absolute-beginners/" target="_blank" rel="noopener">Official beginner index</a> · <a href="research/catalog-audit.json" download>Download catalog audit</a> · <a href="grammar-data.json" download>Download course data</a></p></details><footer class="footer">Videos and their titles belong to Japanese Ammo with Misa. Personal study organizer; not affiliated with the channel. <a href="index.html">Return to the five Hirogaru reading articles →</a></footer></main></div></body></html>'''
(root/'grammar.html').write_text(html)
# Preserve the existing reader exactly apart from adding navigation and its styling.
p=root/'index.html';old=p.read_text();backup=R/'index.before-grammar.html'
if not backup.exists():backup.write_text(old)
if 'aria-label="Study pages"' not in old:
 old=old.replace('</style>','.study-nav{display:flex;gap:1rem;flex-wrap:wrap}.study-nav a{color:#d2e1ec;font-size:.9rem;text-decoration:none}.study-nav a[aria-current]{color:white;text-decoration:underline}\n</style>')
 old=old.replace('<small>Personal reading collection · 05 articles</small>','<nav class="study-nav" aria-label="Study pages"><a href="index.html" aria-current="page">Reading articles</a><a href="grammar.html">Grammar course →</a></nav>')
 p.write_text(old)
audit=[]
for v in catalog:
 a={k:v[k] for k in ['id','url','verified_title','author','checked','verified','oembed_http_status'] if k in v}
 a['classification']='Included in course' if v['id'] in ids else ('Historical link; public metadata unverified' if not v['verified'] else 'Outside grammar course: vocabulary, writing, pronunciation, culture, entertainment or other application material')
 audit.append(a)
(R/'catalog-audit.json').write_text(json.dumps(dict(checked='2026-09-13',method='Public channel and playlist metadata plus YouTube oEmbed; not end-to-end viewing',entries=audit),ensure_ascii=False,indent=2))
print('Rendered',n,'entries;',count,'lessons;',gaps,'gaps;',len(ids),'verified video links')
